<template><div class="page-title">服务工单</div><div class="toolbar"><el-input v-model="keyword" placeholder="主题或工单号" @keyup.enter="load"/><el-select v-model="status" clearable placeholder="状态"><el-option v-for="(v,k) in maps.caseStatus" :key="k" :label="v" :value="k"/></el-select><el-checkbox v-model="overdue">仅超期</el-checkbox><el-button type="primary" @click="open()">新建工单</el-button><el-button @click="load">查询</el-button></div><el-card><el-table :data="rows" :row-class-name="rowClass"><el-table-column prop="caseNo" label="工单号"/><el-table-column prop="subject" label="主题"/><el-table-column prop="priority" label="优先级"/><el-table-column prop="status" label="状态"/><el-table-column prop="slaDueAt" label="SLA截止"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="open(row)">编辑</el-button><el-button link type="warning" @click="escalate(row)">升级</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" title="服务工单"><el-form label-width="90px"><el-form-item label="主题"><el-input v-model="form.subject"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="客户ID"><el-input v-model="form.accountId"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
<script setup>import {ref,onMounted} from 'vue';import {cases} from '../api';import {maps} from '../utils/enums';import {ElMessage} from 'element-plus';const rows=ref([]),keyword=ref(''),status=ref(''),overdue=ref(false),visible=ref(false),form=ref({});async function load(){const d=await cases.list({page:1,size:30,keyword:keyword.value,status:status.value||undefined,overdue:overdue.value||undefined});rows.value=d.records}function open(x){form.value={...(x||{})};visible.value=true}async function save(){if(form.value.id)await cases.update(form.value.id,form.value);else await cases.add(form.value);visible.value=false;load()}async function escalate(x){await cases.escalate(x.id);ElMessage.success('已升级');load()}function rowClass({row}){return row.slaDueAt&&new Date(row.slaDueAt)<new Date()&&!['RESOLVED','CLOSED'].includes(row.status)?'overdue-row':''}onMounted(load)</script><style>.overdue-row td{background:#fff1f0!important;color:#f56c6c}</style>
